using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using RebirthEntityStudio;
public static class NurseOptimizationDelivery {
 const string Out=NurseVisualOptimization.Out;const string Folder=NurseVisualOptimization.Folder;const string Native="Assets/EntityStudioGenerated/RebirthNurseNative";
 public static void SculptAndPalette(){NurseMoeReference.Run();Finish();EyeReview();}
 public static void DistinctFemaleReview(){try{NurseSurfaceFinish.Run();NurseHairWeightFit.Run();Install();NurseNativeBloodBake.Run();NurseHairMaterials.Run();NurseHairContourFit.Run();NurseFaceSculpt.Run();NurseEyeAlignment.Run();Review();EyeReview();}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void DistinctSurfaceComparison(){DistinctFemaleReview();NurseFaceComparison.Run();}
 public static void DistinctPaletteHairReview(){NurseMoeReference.Run();DistinctSurfaceComparison();NurseHairRebuild.Preview();}
 public static void UnifiedFaceReview(){Compare("BeforeUnifiedFaceMask_Face.png","Final_Face.png","UnifiedFaceMask_Before_After.png");NurseHairMaterials.VerifyRoleRefinement();}
 public static void NoNativeWrinkleCandidate(){NurseNativeFaceDetail.NormalDetailStrength=0;Finish();}
 public static void CompleteWithReference(){NurseMoeReference.Run();FromAtlas();HairSwayReview();EyeReview();}
 public static void FromAtlas(){NurseVisualOptimization.AtlasCandidates();Finish();}
 public static void ContoursAndReview(){NurseHairContourFit.Run();NurseFaceSculpt.Run();NurseEyeAlignment.Run();Review();HairSwayReview();Build();EyeReview();}
 public static void HairMaterialsOnly(){Install();NurseHairMaterials.Run();NurseHairContourFit.Run();NurseFaceSculpt.Run();NurseEyeAlignment.Run();Review();HairSwayReview();Build();EyeReview();}
 public static void HairWeightsOnly(){NurseHairWeightFit.Run();Install();Review();HairSwayReview();Build();EyeReview();}
 public static void HairSwayReview(){var go=Model();var body=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");var before=NurseAnatomyRender.WorldSkin(body);var beforePoints=before.vertices;var weights=body.sharedMesh.boneWeights;var hairRoot=body.bones.First(b=>b.name=="Hair_Back_Left");hairRoot.localRotation*=Quaternion.Euler(4,4,0);var after=NurseAnatomyRender.WorldSkin(body);var afterPoints=after.vertices;float maximumHair=0,maximumPinned=0;int moving=0;for(int i=0;i<weights.Length;i++){var w=weights[i];int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] ws={w.weight0,w.weight1,w.weight2,w.weight3};float hair=0;for(int k=0;k<4;k++)if(body.bones[ids[k]].name.StartsWith("Hair_"))hair+=ws[k];float delta=Vector3.Distance(beforePoints[i],afterPoints[i]);if(hair>.001f){maximumHair=Mathf.Max(maximumHair,delta);if(delta>.0001f)moving++;}else maximumPinned=Mathf.Max(maximumPinned,delta);}if(maximumPinned>.00001f||maximumHair<.0001f)throw new Exception("Hair sway skinning did not isolate loose hair");NurseVisualOptimization.Render(go,"Final_Hair_Sway",0,true);File.WriteAllText(Out+"/hair-sway-review.txt","Controlled Editor pose: existing Hair_Back_Left root rotated 4 degrees X/Y. Loose-hair moving vertices="+moving+"; maximum hair displacement="+maximumHair+" m; maximum non-hair displacement="+maximumPinned+" m. No prefab transform writes; this checks skinning isolation, not runtime Jiggle2 physics or independent left/right hair motion.\n");UnityEngine.Object.DestroyImmediate(before);UnityEngine.Object.DestroyImmediate(after);UnityEngine.Object.DestroyImmediate(go);}
 public static void EyeReview(){var nurse=Model();NurseVisualOptimization.Render(nurse,"Nurse_Eyes",0,true);UnityEngine.Object.DestroyImmediate(nurse);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var moe=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));moe.GetComponent<Animator>().enabled=false;moe.GetComponent<LODGroup>().ForceLOD(0);NurseVisualOptimization.Render(moe,"Moe_Eyes",0,true);Compare("Moe_Eyes.png","Nurse_Eyes.png","Moe_Nurse_Eyes_Comparison.png");}
 public static void HairDiagnostic(){var go=Model();NurseVisualOptimization.Render(go,"Diagnostic_Hair_NoNormal",0,true);go=Model();foreach(var r in go.GetComponentsInChildren<SkinnedMeshRenderer>(true)){var source=r.sharedMaterial;var mat=new Material(Shader.Find("Unlit/Texture"));mat.mainTexture=source.HasProperty("_Albedo")?source.GetTexture("_Albedo"):source.GetTexture("_MainTex");r.sharedMaterial=mat;}NurseVisualOptimization.Render(go,"Diagnostic_Hair_Unlit",0,true,true);}

 public static void EyesAndReview(){Finish();}
 public static void Finish(){try{DistinctFemaleReview();Build();}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static GameObject Model(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Native+"/RebirthNurse_Authoring.prefab"));go.GetComponent<Animator>().enabled=false;go.GetComponent<LODGroup>().ForceLOD(0);return go;}
 static void Install(){var rows=new List<string>();var model=Model();var renderer=model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");int level=0;foreach(int count in new[]{20000,9500,3000}){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Blender_"+count+".asset");if(mesh==null)throw new Exception("Optimized mesh missing");if(mesh.normals.Length!=mesh.vertexCount||mesh.tangents.Length!=mesh.vertexCount||mesh.uv.Length!=mesh.vertexCount)throw new Exception("Vertex attributes missing");foreach(var w in mesh.boneWeights){if(Mathf.Abs(w.weight0+w.weight1+w.weight2+w.weight3-1)>.001f)throw new Exception("Weight normalization failed");foreach(int id in new[]{w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3})if(id<0||id>=renderer.bones.Length)throw new Exception("Bone index invalid");}var target=AssetDatabase.LoadAssetAtPath<Mesh>(Native+"/RebirthNurse_LOD"+level+"_0.asset");string name=target.name;target.Clear();target.indexFormat=mesh.indexFormat;target.vertices=mesh.vertices;target.normals=mesh.normals;target.tangents=mesh.tangents;target.uv=mesh.uv;target.boneWeights=mesh.boneWeights;target.bindposes=mesh.bindposes;target.triangles=mesh.triangles;target.bounds=mesh.bounds;target.name=name;if(!target.vertices.SequenceEqual(mesh.vertices)||!target.uv.SequenceEqual(mesh.uv)||!target.triangles.SequenceEqual(mesh.triangles))throw new Exception("Live mesh copy mismatch");EditorUtility.SetDirty(target);rows.Add("LOD"+level+" triangles="+target.triangles.Length/3+" vertices="+target.vertexCount+" normalizedWeights=PASS bindposes="+target.bindposes.Length);level++;}
  string manifestPath=RebirthEntityPrefabExporter.ManifestPath(Native+"/RebirthNurse.prefab");var manifest=JsonUtility.FromJson<RebirthEntityPrefabManifest>(File.ReadAllText(manifestPath));manifest.nativeTextureAssetPaths=new[]{"Normal","Feral","Special"}.Select(t=>Folder+"/Atlas_RMOE_"+t+".png").ToArray();File.WriteAllText(manifestPath,JsonUtility.ToJson(manifest,true));AssetDatabase.Refresh();AssetDatabase.SaveAssets();
  if(model.transform.Find("Origin").GetComponentsInChildren<Transform>(true).Length!=87)throw new Exception("Skeleton count changed");if(model.GetComponentsInChildren<Rigidbody>(true).Length!=11||model.GetComponentsInChildren<CharacterJoint>(true).Length!=10||model.GetComponentsInChildren<CapsuleCollider>(true).Length!=12)throw new Exception("Physics count changed");if(!model.GetComponent<Animator>().avatar.isValid||!model.GetComponent<Animator>().avatar.isHuman)throw new Exception("Avatar invalid");rows.Add("Existing skeleton=87; rigidbodies=11; joints=10; capsules=12 including large blocker; valid humanoid Avatar=PASS. Skeleton transforms/collider fields not edited by optimization.");File.WriteAllLines(Out+"/optimized-mesh-audit.txt",rows);UnityEngine.Object.DestroyImmediate(model);
 }
 static void Review(){var view=Model();var body=view.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");
  for(int i=0;i<3;i++){body.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Native+"/RebirthNurse_LOD"+i+"_0.asset");NurseVisualOptimization.Render(view,"Final_LOD"+i,0,false);}
  body.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Native+"/RebirthNurse_LOD0_0.asset");NurseVisualOptimization.Render(view,"Final_Face",0,true);
  foreach(int angle in new[]{0,90,180,270}){view.transform.rotation=Quaternion.Euler(0,angle,0);NurseVisualOptimization.Render(view,"Final_Hair_"+angle,0,true);}
  foreach(int angle in new[]{0,180}){view.transform.rotation=Quaternion.Euler(0,angle,0);NurseVisualOptimization.Render(view,"Final_Feet_"+angle,0,false);NurseVisualOptimization.Render(view,"Final_Tears_"+angle,0,false);if(angle==180)NurseVisualOptimization.Render(view,"Final_Back",0,false);}
  UnityEngine.Object.DestroyImmediate(view);
  var poses=new List<string>();foreach(string category in new[]{"walkForward","melee","Pain"}){var go=Model();var animator=go.GetComponent<Animator>();var clip=animator.runtimeAnimatorController.animationClips.First(c=>c.name.StartsWith(category,StringComparison.OrdinalIgnoreCase)&&c.length>.2f);AnimationMode.StartAnimationMode();AnimationMode.BeginSampling();AnimationMode.SampleAnimationClip(go,clip,clip.length*.4f);AnimationMode.EndSampling();NurseVisualOptimization.Render(go,"Final_Pose_"+category,0,false);foreach(var r in go.GetComponentsInChildren<SkinnedMeshRenderer>(true)){var skin=NurseAnatomyRender.WorldSkin(r);if(skin.vertices.Any(v=>float.IsNaN(v.x)||float.IsInfinity(v.x)))throw new Exception("Nonfinite pose vertex");UnityEngine.Object.DestroyImmediate(skin);}poses.Add("Editor sampled pose="+clip.name+" finite skin=PASS; visual capture only, not gameplay.");AnimationMode.StopAnimationMode();UnityEngine.Object.DestroyImmediate(go);}File.WriteAllLines(Out+"/sampled-poses.txt",poses);
  Compare("MoeFace_Current.png","Final_Face.png","Moe_Nurse_Face_Comparison.png");Compare("Moe_Current_Body.png","Final_LOD0.png","Moe_Nurse_Body_Comparison.png");Compare("Original_Face_Lit.png","Final_Face.png","Face_Before_After.png");Compare("Original_FullBody.png","Final_LOD0.png","Body_Before_After.png");
 }
 static void Compare(string a,string b,string path){var left=new Texture2D(2,2);left.LoadImage(File.ReadAllBytes(Out+"/"+a));var right=new Texture2D(2,2);right.LoadImage(File.ReadAllBytes(Out+"/"+b));if(left.width!=right.width||left.height!=right.height)throw new Exception("Comparison frame mismatch");var both=new Texture2D(left.width*2,left.height,TextureFormat.RGB24,false);both.SetPixels(0,0,left.width,left.height,left.GetPixels());both.SetPixels(left.width,0,right.width,right.height,right.GetPixels());both.Apply();File.WriteAllBytes(Out+"/"+path,both.EncodeToPNG());}
 static void Build(){string build=Out+"/Build_"+DateTime.Now.ToString("yyyyMMdd_HHmmss");var receipt=RebirthEntityBundleBuilder.BuildAndVerify(Native+"/RebirthNurse.prefab",build);File.WriteAllText(Out+"/receipt.json",JsonUtility.ToJson(receipt,true));var bundle=AssetBundle.LoadFromFile(receipt.bundlePath);var rows=new List<string>();var textures=new HashSet<Texture2D>(bundle.LoadAllAssets<Texture2D>());foreach(var mat in bundle.LoadAllAssets<Material>())foreach(string property in mat.GetTexturePropertyNames()){var texture=mat.GetTexture(property) as Texture2D;if(texture!=null)textures.Add(texture);}foreach(var prefab in bundle.LoadAllAssets<GameObject>())foreach(var renderer in prefab.GetComponentsInChildren<Renderer>(true))foreach(var mat in renderer.sharedMaterials)if(mat!=null)foreach(string property in mat.GetTexturePropertyNames()){var texture=mat.GetTexture(property) as Texture2D;if(texture!=null)textures.Add(texture);}foreach(var t in textures){bool large=t.name.Contains("Albedo")||t.name=="Atlas_Normal";int cap=large?2048:512;if(t.width>cap||t.height>cap)throw new Exception("Texture cap exceeded "+t.name);rows.Add(t.name+"="+t.width+"x"+t.height+" "+t.format);}bundle.Unload(true);File.WriteAllLines(Out+"/bundle-textures.txt",rows);Debug.Log("NURSE_OPTIMIZATION_DELIVERY_READY");}
}









